<div class="card"><h2 class="section-title">Akun Guru</h2><div class="form-grid">
<div class="field"><label>Nama Lengkap *</label><input name="name" value="{{ old('name',$teacher?->user?->name) }}" required></div><div class="field"><label>Email Login *</label><input type="email" name="email" value="{{ old('email',$teacher?->user?->email) }}" required></div>
<div class="field"><label>{{ $teacher ? 'Password Baru' : 'Password *' }}</label><input type="password" name="password" {{ $teacher?'':'required' }}><small>{{ $teacher?'Kosongkan jika tidak diubah.':'Minimal 8 karakter.' }}</small></div><div class="field"><label>Konfirmasi Password</label><input type="password" name="password_confirmation" {{ $teacher?'':'required' }}></div></div></div>
<div class="card"><h2 class="section-title">Profil Guru</h2><div class="form-grid">
<div class="field"><label>Nomor Pegawai</label><input name="employee_number" value="{{ old('employee_number',$teacher?->employee_number) }}"></div><div class="field"><label>NIP</label><input name="nip" value="{{ old('nip',$teacher?->nip) }}"></div>
<div class="field"><label>Jenis Kelamin</label><select name="gender"><option value="">- Pilih -</option><option value="L" @selected(old('gender',$teacher?->gender)==='L')>Laki-laki</option><option value="P" @selected(old('gender',$teacher?->gender)==='P')>Perempuan</option></select></div><div class="field"><label>No. HP</label><input name="phone" value="{{ old('phone',$teacher?->phone) }}"></div><div class="field full"><label>Alamat</label><textarea name="address">{{ old('address',$teacher?->address) }}</textarea></div></div></div>
